const STATUS_FRACTION = { met: 1.0, partial: 0.5, missing: 0.0 };
// وزن كل معيار. كانت المعايير متساوية، فكان الجنسُ يساوي الوظيفةَ نفسها: مهندس
// بترول تقدّم لوظيفة مساعد موارد بشرية في بغداد ففشل في الوظيفة والموقع والقطاع،
// ونجح في الجنس والبكالوريوس ولقب «Senior» الذي كتبه بنفسه — فخرج بـ50% و«Consider»
// بينما السرد نفسه يقول «ليس مناسباً». الوزن يجعل ملاءمة الدور تحكم النتيجة.
// gender = 0 عمداً: يُسجَّل كشرط لصاحب العمل ولا يُحتسب جدارةً.
const CRITERION_WEIGHT = {
  position: 25,
  experienceyears: 15,
  skills: 15,
  careerlevel: 10,
  educationlevel: 10,
  languages: 10,
  industrytype: 8,
  location: 5,
  managementtrack: 2,
  gender: 0,
};
const DEFAULT_WEIGHT = 8; // معيار مخصّص من صاحب العمل — وزن متوسط
const COVERAGE_FLOOR = 0.5;
const T_ADVANCE = 70;
const T_CONSIDER = 49;
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
function txt(v) { return String(v == null ? '' : v).trim(); }
function toArray(v) { if (Array.isArray(v)) return v.filter((x) => txt(x)); const s = txt(v); return s ? [s] : []; }
function getAssessment(item) { const j = item.json || {}; if (j.output && typeof j.output === 'object') return j.output; if (j.criteria || j.integrity_concerns) return j; const raw = j.text || j.response || j.data || ''; const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e) {} } return {}; }
/** المفتاح مدفون في المعرّف: `preset__position__d660d64d` → `position`. */
function weightForId(id, key) {
  const k = norm(key) || norm(String(id).split('__')[1] || '');
  return Object.prototype.hasOwnProperty.call(CRITERION_WEIGHT, k) ? CRITERION_WEIGHT[k] : DEFAULT_WEIGHT;
}
/** يعيد Map من معرّف المعيار إلى وزنه. */
function getRubricWeights(item) {
  const SKIP = new Set(['rolekey', 'labelkey', 'rolematchsource', 'evaluationlanguage']);
  let arr = [];
  try {
    let c = $('Webhook').first().json.body.evaluationRubric;
    if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) { c = []; } }
    if (Array.isArray(c)) arr = c;
  } catch (e) {}
  const map = new Map();
  for (const c of arr) {
    const id = txt(c && c.id);
    const key = norm(c && c.key);
    if (!id || SKIP.has(key)) continue;
    map.set(id, weightForId(id, key));
  }
  return map;
}
const out = [];
for (const item of $input.all()) {
  const a = getAssessment(item);
  const weights = getRubricWeights(item);
  // المقام هو الوزن الكامل لكل المعايير المطلوبة، لا ما جرى تقييمه فقط. القسمة على
  // المُقيَّم كانت تحذف المعايير غير المقيَّمة من الحساب، فلا يُكلَّف المرشح شيئاً
  // حين لا يُقدّم دليلاً — وهو نفس العطب الذي أُصلح في المرحلة الثانية.
  let totalWeight = 0;
  for (const w of weights.values()) totalWeight += w;
  const items = Array.isArray(a.criteria) ? a.criteria : [];
  let assessedWeight = 0, earned = 0, assessedCount = 0;
  const criteriaResults = [];
  const seen = new Set();
  for (const c of items) {
    const id = txt(c && (c.criterionId != null ? c.criterionId : c.id));
    if (!id || !weights.has(id) || seen.has(id)) continue;
    seen.add(id);
    const w = weights.get(id);
    const st = norm(c.status);
    if (st === 'not_assessed' || st === 'not assessed' || !(st in STATUS_FRACTION)) { criteriaResults.push({ criterionId: id, status: 'not_assessed' }); continue; }
    earned += STATUS_FRACTION[st] * w;
    assessedWeight += w;
    assessedCount += 1;
    criteriaResults.push({ criterionId: id, status: st, evidence: txt(c.evidence) });
  }
  const integrity = (Array.isArray(a.integrity_concerns) ? a.integrity_concerns : []).filter((c) => txt(c && c.concern) && txt(c && c.quote));
  const coverage = totalWeight > 0 ? assessedWeight / totalWeight : 0;
  let status = 'scored';
  let score = totalWeight > 0 && assessedCount > 0 ? Math.round((earned / totalWeight) * 100) : null;
  const noCriteria = weights.size === 0 || totalWeight === 0;
  if (noCriteria || coverage < COVERAGE_FLOOR) status = 'insufficient_data';
  let recommendation;
  if (status === 'insufficient_data') { recommendation = 'Consider'; score = null; } else { recommendation = score >= T_ADVANCE ? 'Hire' : score >= T_CONSIDER ? 'Consider' : 'Reject'; }
  if (integrity.length) { if (status !== 'insufficient_data') status = 'manual_review'; if (recommendation === 'Hire') recommendation = 'Consider'; }
  let fit = txt(a.fit_for_role);
  let summary = txt(a.summary);
  const notes = [];
  if (integrity.length) notes.push('Integrity concern (' + integrity.map((c) => txt(c.concern)).join('; ') + ') -- mandatory human review.');
  if (status === 'insufficient_data') notes.push(noCriteria ? 'No employer criteria provided -- human review.' : 'Too few criteria could be assessed -- human review.');
  const note = notes.length ? ('NOTE: ' + notes.join(' ')) : '';
  const finalHr = note ? (fit ? (fit + '\n\n' + note) : note) : (fit || 'Screening completed; see the criteria breakdown.');
  if (note) summary = summary ? (summary + '\n\n' + note) : note;
  const redFlags = integrity.map((c) => txt(c.concern));
  out.push({ json: { valid: true, evaluation: { overall_score: score, recommendation, strengths: toArray(a.strengths), weaknesses: toArray(a.weaknesses), summary: summary || 'Screening completed.', fit_for_role: fit || summary || 'See the criteria breakdown.', final_hr_evaluation: finalHr, red_flags: redFlags }, criteria_results: criteriaResults, screening_coverage: Math.round(coverage * 100) / 100, status } });
}
return out;
